<?php
 namespace QQWorld\Security\Test\Unit\Model\Plugin; use QQWorld\Framework\TestFramework\Unit\Helper\ObjectManager; use QQWorld\Security\Model\SecurityCookie; class LoginControllerTest extends \PHPUnit\Framework\TestCase { protected $controller; protected $messageManagerMock; protected $adminSessionsManagerMock; protected $securityCookieMock; protected $backendControllerAuthLoginMock; protected $requestMock; protected $objectManager; public function setUp() { $this->objectManager = new ObjectManager($this); $this->messageManagerMock = $this->createMock(\QQWorld\Framework\Message\ManagerInterface::class); $this->adminSessionsManagerMock = $this->createPartialMock( \QQWorld\Security\Model\AdminSessionsManager::class, ['getLogoutReasonMessageByStatus'] ); $this->securityCookieMock = $this->createPartialMock( SecurityCookie::class, ['getLogoutReasonCookie', 'deleteLogoutReasonCookie'] ); $this->backendControllerAuthLoginMock = $this->createPartialMock( \QQWorld\Backend\Controller\Adminhtml\Auth\Login::class, ['getRequest', 'getUrl'] ); $this->requestMock = $this->createPartialMock(\QQWorld\Framework\App\Request\Http::class, ['getUri']); $this->controller = $this->objectManager->getObject( \QQWorld\Security\Model\Plugin\LoginController::class, [ 'messageManager' => $this->messageManagerMock, 'sessionsManager' => $this->adminSessionsManagerMock, 'securityCookie' => $this->securityCookieMock ] ); } public function testBeforeExecute() { $logoutReasonCode = 2; $uri = '/uri/'; $errorMessage = 'Error Message'; $this->securityCookieMock->expects($this->once()) ->method('getLogoutReasonCookie') ->willReturn($logoutReasonCode); $this->backendControllerAuthLoginMock->expects($this->once()) ->method('getRequest') ->willReturn($this->requestMock); $this->requestMock->expects($this->once()) ->method('getUri') ->willReturn($uri); $this->backendControllerAuthLoginMock->expects($this->once()) ->method('getUrl') ->willReturn($uri); $this->adminSessionsManagerMock->expects($this->once()) ->method('getLogoutReasonMessageByStatus') ->with($logoutReasonCode) ->willReturn($errorMessage); $this->messageManagerMock->expects($this->once()) ->method('addError') ->with($errorMessage); $this->securityCookieMock->expects($this->once()) ->method('deleteLogoutReasonCookie') ->willReturnSelf(); $this->controller->beforeExecute($this->backendControllerAuthLoginMock); } } 